/**
 * Generates supabase/seed.sql from the product data in src/data/products.ts.
 * Run:  npm run seed:generate
 */
import fs from 'node:fs';
import path from 'node:path';
import { MOCK_PRODUCTS, POPULAR_CATEGORY_CARDS } from '../src/data/products.ts';

const q = (v: string) => `'${v.replace(/'/g, "''")}'`;
const num = (v: number) => v.toFixed(2);
const json = (v: unknown) => `${q(JSON.stringify(v))}::jsonb`;

const lines: string[] = [
  '-- Generated by scripts/generate-seed.ts. Do not edit by hand.',
  '-- Safe to re-run: categories are refreshed; existing products are left untouched (so admin edits are kept).',
  '',
];

for (const c of POPULAR_CATEGORY_CARDS) {
  lines.push(
    `insert into public.categories (slug, name, tagline, description, starting_price_aed) values (` +
      `${q(c.id)}, ${q(c.title)}, ${q(c.badge)}, ${q(c.subtitle)}, ${num(c.startingPrice)}) ` +
      `on conflict (slug) do update set name = excluded.name, tagline = excluded.tagline, ` +
      `description = excluded.description, starting_price_aed = excluded.starting_price_aed;`
  );
}
lines.push('');

for (const p of MOCK_PRODUCTS) {
  const details = {
    gallery: p.gallery ?? [],
    longDescription: p.longDescription ?? [],
    highlights: p.highlights ?? [],
    tastingNotes: p.tastingNotes ?? null,
    boxContents: p.boxContents ?? [],
  };
  lines.push(
    `insert into public.products (slug, title, brand, category, price_aed, original_price_aed, puff_count, ` +
      `nicotine_strength, flavor_profile, image, stock_count, in_stock, is_offer, description, ` +
      `flavors, nicotine_options, specs, details) values (` +
      [
        q(p.id),
        q(p.title),
        q(p.brand),
        q(p.category),
        num(p.price),
        p.originalPrice ? num(p.originalPrice) : 'null',
        p.puffCount ? q(p.puffCount) : 'null',
        q(p.nicotineStrength),
        q(p.flavorProfile),
        q(p.image),
        String(p.stockCount ?? 48),
        String(p.inStock),
        String(Boolean(p.isOffer)),
        q(p.description),
        json(p.variants.flavors),
        json(p.variants.nicotineOptions),
        json(p.specs),
        json(details),
      ].join(', ') +
      `) on conflict (slug) do nothing;`
  );
}

